    41	      case 'ArrowDown':
    42	        if (focused < size * (size - 1)) next += size;
    43	        break;
    44	      default:
    45	        return;
    46	    }
    47	    // Arrows move focus, including stopping at an edge, instead of scrolling the page.
    48	    event.preventDefault();
    49	    element.current?.querySelectorAll('button').item(next)?.focus({ preventScroll: true });
    50	  }
    51	  return { viewport, element, focused, focusRemembered, cardFocused, cardKeyDown };
    52	}
    24	function cardClicked(card: HTMLElement): void {
    25	  card.scrollIntoView(NEAREST);
    26	}
    27	
    28	export function Board({ game, ref, activate }: BoardProps) {
    29	  const { size, deck, matched, selection } = game;
    30	  const { viewport, element, focused, focusRemembered, cardFocused, cardKeyDown } =
    31	    useBoardFocus(size);
    32	  useImperativeHandle(ref, () => ({ focusRemembered }), [focusRemembered]);
    33	  // A clock tick keeps both arrays, so the cards' props stay equal and no card renders again.
    34	  const faceUp = useMemo(() => faceUpCards({ matched, selection }), [matched, selection]);
    35	  const matchedCards = useMemo(() => new Set(matched), [matched]);
    36	  // The game passes a new handler on each render. Cards keep one callback that calls the latest.
    37	  const latestActivate = useRef(activate);
    38	  useLayoutEffect(() => {
    39	    latestActivate.current = activate;
    40	  });
    41	  const activateCard = useCallback((index: number) => latestActivate.current(index), []);
    42	  const style: BoardStyle = { '--grid-size': size };
    43	  return (
    44	    <div
    45	      ref={viewport}
    46	      className="board-viewport"
    47	      role="region"
    48	      aria-label="Game board"
    49	      aria-describedby="board-help"
    50	    >
    51	      <div className="board" ref={element} style={style} onKeyDown={cardKeyDown}>
    52	        {deck.map((face, index) => (
    53	          <Card
    54	            key={index}
    55	            index={index}
    56	            size={size}
    57	            face={faceUp.has(index) ? face : null}
    58	            matched={matchedCards.has(index)}
"}
